/**
 * V-PLUGIN-CSV-FUNCTIONAL: CSV Parser end-to-end execution.
 *
 * REQ: REQ-3.4.1.12 (CSV parser), REQ-3.4.3.3 (table variable output)
 * Each fixture chains CSV nodes (each binding its
 * outputs to a variable) with Log nodes whose message is an expression over
 * those variables; the expected console lines are the ground truth in
 * expected.json (generated by running the real plugin). Assertions are anchored
 * on the emitted log output / run status, never on mere element presence.
 *
 *   parse-typing   P1-P17  auto/string typing, guards, empty->None/default
 *   parse-schema   S1-S3b  schema mapping (name/position) + skip_row/replace_default
 *   transform      T1-T12  declarative sort/filter (literal, expression, AND/OR,
 *                           two blocks, index ref, workflow-var + reference-expr)
 *   serialize      Z1-Z8   table -> CSV text (header/delimiter/None/bool/float/round-trip)
 *   expr-methods           Table.filter/order_by chaining in the expression sandbox
 *
 * Aborting permutations (run must FAIL at the node with the exact message) live
 * in their own fixtures because they terminate the run:
 *   parse-mismatch-fail  S4  on_mismatch=fail
 *   transform-unknown-op T9  unknown filter operator
 *   serialize-wrong-type Z7  serialize a non-table
 *
 * The serialize/schema fixtures use the UI-faithful literal variable_ref form
 * (bare variable name, no expressionFields).
 *
 * Run: ./scripts/e2e-targeted-local.sh functional/csv-parser/v-plugin-csv-functional.spec.ts
 */

import { test, expect, type Page } from '../../helpers/playwright-fixtures'
import { getLogTexts, getLogLines } from '../../helpers/log-reader'
import { importValidateAndNavigate } from '../../helpers/fixture-import'
import { selectEnvironment } from '../../helpers/workbench'
import fs from 'fs'
import path from 'path'

function loadFixture(name: string): Record<string, unknown> {
  return JSON.parse(
    fs.readFileSync(path.resolve(__dirname, `${name}.fixture.json`), 'utf-8'),
  ) as Record<string, unknown>
}

const EXPECTED: Record<string, string[]> = JSON.parse(
  fs.readFileSync(path.resolve(__dirname, 'expected.json'), 'utf-8'),
)

async function runToTerminal(page: Page): Promise<string> {
  await selectEnvironment(page)
  await page.locator('[data-testid="run-button"]').click()
  const status = page.locator('[data-testid="workflow-status"]')
  await expect(status).not.toHaveAttribute('data-status', 'idle', { timeout: 10_000 })
  await expect(status).not.toHaveAttribute('data-status', 'running', { timeout: 60_000 })
  return (await status.getAttribute('data-status')) ?? 'unknown'
}

// ---------------------------------------------------------------------------
// Passing fixtures - every expected console line must appear.
// ---------------------------------------------------------------------------

const PASSING = ['parse-typing', 'parse-schema', 'transform', 'serialize', 'expr-methods']

for (const name of PASSING) {
  test(`CSV functional: ${name}`, async ({ page }) => {
    test.setTimeout(120_000)
    await importValidateAndNavigate(page, loadFixture(name))

    const status = await runToTerminal(page)
    const logs = await getLogTexts(page)
    if (status !== 'passed') {
      const lines = await getLogLines(page)
      test.info().annotations.push({ type: 'error-logs', description: JSON.stringify(lines.slice(-20)) })
    }
    expect(status, `workflow ${name} must pass`).toBe('passed')

    const missing = EXPECTED[name].filter((line) => !logs.includes(line))
    expect(
      missing,
      `Missing expected console lines for ${name}:\n${JSON.stringify(missing, null, 2)}\n\nGot:\n${logs.join('\n')}`,
    ).toEqual([])
  })
}

// ---------------------------------------------------------------------------
// Aborting fixtures: the run FAILS at the node with the exact error message.
// ---------------------------------------------------------------------------

const ABORTING: Array<{ name: string; node: string; errorText: string }> = [
  {
    name: 'parse-mismatch-fail',
    node: 'parse-s4',
    errorText: "Type mismatch in column 'age': 'abc' is not a valid integer",
  },
  {
    name: 'transform-unknown-op',
    node: 't9',
    errorText: "Unknown filter operator: 'bogus'",
  },
  {
    // The table input is a variable_ref: a non-table variable is rejected at
    // parameter resolution (the type-check fires before execute), so the run
    // fails with the resolution-layer message rather than the plugin's own
    // "must be a table" TypeError (which the backend unit test still covers).
    name: 'serialize-wrong-type',
    node: 'z7-serialize',
    errorText: "Parameter 'table' expects table, got str",
  },
]

for (const { name, node, errorText } of ABORTING) {
  test(`CSV functional abort: ${name}`, async ({ page }) => {
    test.setTimeout(120_000)
    await importValidateAndNavigate(page, loadFixture(name))

    const status = await runToTerminal(page)
    expect(status, `workflow ${name} must fail`).toBe('failed')

    await expect(page.locator(`[data-testid="workflow-node-${node}"]`)).toHaveAttribute(
      'data-execution-status',
      'failed',
    )

    const lines = await getLogLines(page)
    expect(
      lines.some((l) => l.includes(errorText)),
      `Expected console ERROR containing:\n  ${errorText}\nGot:\n${lines.join('\n')}`,
    ).toBeTruthy()
  })
}
